+                throw new StoreUpdateFailedException(String.format(
+                        "Cannot forget rule '%s': violation file '%s' could not be deleted",
+                        description, fileName), e);
+            }
+        }
+        storedRules.remove(description);
+    }
+
+    private boolean isSharedFile(String description, Path violationFile) {
+        for (Map.Entry<Object, Object> entry : storedRules.entries().entrySet()) {
+            String otherDescription = String.valueOf(entry.getKey());
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = String.valueOf(entry.getValue());
+            if (otherName.equals(violationFile.getFileName().toString())) {
+                return true;
+            }
+            Path otherFile = pathForNameOrNull(otherName);
+            if (otherFile != null && sameFile(violationFile, otherFile)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeState) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(new File(storeFolder, fileName)), UTF_8));
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void write(List<String> violations, Path ruleDetailsFile) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetailsFile, builder.toString().getBytes(UTF_8));
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private Path validateStoreFileName(String fileName) {
+        if (fileName == null || fileName.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("A rule violation file name must not be empty");
+        }
+        try {
+            Path relative = Paths.get(fileName);
+            Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+            Path resolved = folder.resolve(relative).normalize();
+            if (relative.isAbsolute() || !folder.equals(resolved.getParent())) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Violation file name '%s' does not name a file directly in the store folder", fileName));
+            }
+            return resolved;
+        } catch (InvalidPathException e) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Violation file name '%s' is not a valid path", fileName), e);
+        }
+    }
+
+    private void rejectIfIndexFile(Path path, String fileName) {
+        Path index = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME).toAbsolutePath().normalize();
+        if (path.equals(index) || sameFile(path, index)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Violation file name '%s' leads to the stored.rules index", fileName));
+        }
+    }
+
+    private IntegrityReport inspectIntegrity() {
+        List<IntegrityEntry> entries = new ArrayList<>();
+        for (Map.Entry<Object, Object> entry : storedRules.entries().entrySet()) {
+            String description = String.valueOf(entry.getKey());
+            String fileName = String.valueOf(entry.getValue());
+            Path path = pathForNameOrNull(fileName);
+            boolean regularDirectFile = path != null && isRegularFileDirectlyInFolder(path) && !isIndexFile(path);
+            boolean broken = !regularDirectFile;
+            boolean resolved = !broken && containsNoViolations(path);
+            String derivedName = null;
+            if (!randomFileNames) {
+                derivedName = createAndValidateFileName(description);
+            }
+            entries.add(new IntegrityEntry(description, fileName, path, broken, resolved, derivedName));
+        }
+
+        markSharedEntries(entries);
+        Map<String, List<IntegrityEntry>> entriesByDerivedName = new HashMap<>();
+        for (IntegrityEntry entry : entries) {
+            if (entry.derivedName != null) {
+                entriesByDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (List<IntegrityEntry> colliding : entriesByDerivedName.values()) {
+            if (colliding.size() > 1) {
+                for (IntegrityEntry entry : colliding) {
+                    entry.colliding = true;
+                }
+            }
+        }
+        for (IntegrityEntry entry : entries) {
+            entry.misplaced = entry.derivedName != null && !entry.fileName.equals(entry.derivedName);
+            if (entry.misplaced) {
+                Path derivedPath = pathForNameOrNull(entry.derivedName);
+                entry.occupied = derivedPath == null
+                        || isIndexFile(derivedPath)
+                        || hasEntryNamed(entry.derivedName)
+                        || existsWithoutFollowingLinks(derivedPath);
+            }
+        }
