+    private void markSharedEntries(List<IntegrityEntry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                IntegrityEntry left = entries.get(i);
+                IntegrityEntry right = entries.get(j);
+                if (left.fileName.equals(right.fileName) || sameFile(left.path, right.path)) {
+                    left.shared = true;
+                    right.shared = true;
+                }
+            }
+        }
+    }
