+    private boolean hasEntryNamed(String name) {
+        for (Map.Entry<Object, Object> entry : storedRules.entries().entrySet()) {
+            if (name.equals(String.valueOf(entry.getValue()))) {
+                return true;
+            }
+        }
+        return false;
+    }
