+    private List<String> findUnownedFiles(List<IntegrityEntry> entries) {
+        List<String> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                if (isIndexFile(file) || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (IntegrityEntry entry : entries) {
+                    if (sameFile(file, entry.path)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
