+    private boolean containsNoViolations(Path path) {
+        try {
+            byte[] bytes = Files.readAllBytes(path);
+            return ONLY_LINE_BREAKS_PATTERN.matcher(new String(bytes, UTF_8)).matches();
+        } catch (IOException e) {
+            return false;
+        }
+    }
